import { test, expect } from '@playwright/test';

test.describe('Form Submission Success Feedback', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/form'); // Replace with the actual URL of the form
  });

  test('should display success message on valid form submission', async ({ page }) => {
    await page.getByLabel('Name').fill('John Doe');
    await page.getByLabel('Email').fill('john.doe@example.com');
    await page.getByLabel('Message').fill('This is a test message.');
    await page.getByRole('button', { name: 'Submit' }).click();

    const successMessage = await page.getByText('Thank you for your submission!');
    await expect(successMessage).toBeVisible();
  });

  test('should not display success message on invalid form submission', async ({ page }) => {
    await page.getByLabel('Email').fill('invalid-email');
    await page.getByRole('button', { name: 'Submit' }).click();

    const successMessage = page.getByText('Thank you for your submission!');
    await expect(successMessage).not.toBeVisible();
  });
});
